<?php $currentPage='notifications'; require __DIR__.'/../layouts/header.php'; ?><div class="page-head"><div><span class="eyebrow">NOTIFICATIONS</span><h1>مركز الإشعارات</h1><p>تنبيهات النظام وسجل قراءتها.</p></div></div><div class="stack"><?php foreach($items as $n):?><div class="card notification <?=!$n['read_at']?'unread':''?>"><div><strong><?=e($n['subject'])?></strong><p><?=nl2br(e($n['message']))?></p><small><?=e($n['created_at'])?> · <?=e(status_label($n['status']))?></small></div><?php if(!$n['read_at']):?><form method="post" action="/?page=notifications&action=read"><?php echo csrf_field();?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn small">تحديد كمقروء</button></form><?php endif;?></div><?php endforeach;?><?php if(!$items):?><div class="empty">لا توجد إشعارات.</div><?php endif;?></div><?php require __DIR__.'/../layouts/footer.php'; ?>
